import{_ as a,a0 as o,w as u,s,I as n,x as t,a1 as r,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"守衞自由的 Linux 世界 | LCTT x X-CMD","titleTemplate":false,"description":"守衞自由的 Linux 世界 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"守衞自由的 Linux 世界 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"守衞自由的 Linux 世界 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20141223 Defending the Free Linux World","title":"守衞自由的 Linux 世界","tag":"201509","desc":""},"relativePath":"201509/20141223 Defending the Free Linux World.md","filePath":"[post].md"}'),d={name:"201509/20141223 Defending the Free Linux World.md"};function x(L,e,m,f,h,T){const i=o("Link");return u(),s("div",null,[e[24]||(e[24]=n("h1",{id:"守衞自由的-linux-世界",tabindex:"-1"},[t("守衞自由的 Linux 世界 "),n("a",{class:"header-anchor",href:"#守衞自由的-linux-世界","aria-label":"Permalink to “守衞自由的 Linux 世界”"},"​")],-1)),e[25]||(e[25]=n("p",null,[n("img",{src:"http://www.linuxinsider.com/ai/908455/open-invention-network.jpg",alt:""})],-1)),e[26]||(e[26]=n("p",null,[n("strong",null,"合作是開源的一部分。OIN 的 CEO Keith Bergelt 解釋説，開放創新網絡（Open Invention Network）模式允許眾多企業和公司決定它們該在哪較量，在哪合作。隨着開源的演變，“我們需要為合作創造渠道，否則我們將會有幾百個團體把數十億美元花費到同樣的技術上。”")],-1)),n("p",null,[r(i,{href:"http://www.openinventionnetwork.com/"},{default:l(()=>[...e[0]||(e[0]=[t("開放創新網絡（Open Invention Network）",-1)])]),_:1}),e[1]||(e[1]=t("，即 OIN，正在全球範圍內開展讓 Linux 遠離專利訴訟的傷害的活動。它的努力得到了一千多個公司的熱烈回應，它們的加入讓這股力量成為了歷史上最大的反專利管理組織。",-1))]),n("p",null,[e[3]||(e[3]=t("開放創新網絡以白帽子組織的身份創建於2005年，目的是保護 Linux 免受來自許可證方面的困擾。包括 Google、 IBM、 NEC、 Novell、 Philips、 ",-1)),r(i,{href:"http://www.redhat.com/"},{default:l(()=>[...e[2]||(e[2]=[t("Red Hat",-1)])]),_:1}),e[4]||(e[4]=t(" 和 Sony 這些成員的董事會給予了它可觀的經濟支持。世界範圍內的多個組織通過簽署自由 OIN 協議加入了這個社區。",-1))]),e[27]||(e[27]=p('<p>創立開放創新網絡的組織成員把它當作利用知識產權保護 Linux 的大膽嘗試。它的商業模式非常的難以理解。它要求它的成員採用免版權許可證，並永遠放棄由於 Linux 相關知識產權起訴其他成員的機會。</p><p>然而，從 Linux 收購風波——想想服務器和雲平台——那時起，保護 Linux 知識產權的策略就變得越加的迫切。</p><p>在過去的幾年裏，Linux 的版圖曾經歷了一場變革。OIN 不必再向人們解釋這個組織的定義，也不必再解釋為什麼 Linux 需要保護。據 OIN 的 CEO Keith Bergelt 説，現在 Linux 的重要性得到了全世界的關注。</p><p>“我們已經見到了一場人們瞭解到 OIN 如何讓合作受益的文化變革，”他對 LinuxInsider 説。</p><h3 id="如何運作" tabindex="-1">如何運作 <a class="header-anchor" href="#如何運作" aria-label="Permalink to “如何運作”">​</a></h3><p>開放創新網絡使用專利權的方式創建了一個協作環境。這種方法有助於確保創新的延續。這已經使很多軟件廠商、顧客、新型市場和投資者受益。</p><p>開放創新網絡的專利證可以讓任何公司、公共機構或個人免版權使用。這些權利的獲得建立在簽署者同意不會專為了維護專利而攻擊 Linux 系統的基礎上。</p><p>OIN 確保 Linux 的源代碼保持開放的狀態。這讓編程人員、設備廠商、獨立軟件開發者和公共機構在投資和使用 Linux 時不用過多的擔心知識產權的問題。這讓對 Linux 進行重新打包、嵌入和使用的公司省了不少錢。</p><p>“隨着版權許可證越來越廣泛的使用，對 OIN 許可證的需求也變得更加的迫切。現在，人們正在尋找更加簡單或更實用的解決方法”，Bergelt 説。</p><p>OIN 法律防禦援助對成員是免費的。成員必須承諾不對 OIN 名單上的軟件發起專利訴訟。為了保護他們的軟件，他們也同意提供他們自己的專利。最終，這些保證將讓幾十萬的交叉許可通過該網絡相互連接起來，Bergelt 如此解釋道。</p><h3 id="填補法律漏洞" tabindex="-1">填補法律漏洞 <a class="header-anchor" href="#填補法律漏洞" aria-label="Permalink to “填補法律漏洞”">​</a></h3>',11)),n("p",null,[e[6]||(e[6]=t("“OIN 正在做的事情是非常必要的。它提供另一層 IP （知識產權）保護，”",-1)),r(i,{href:"http://www.law.uh.edu/"},{default:l(()=>[...e[5]||(e[5]=[t("休斯頓法律中心大學",-1)])]),_:1}),e[7]||(e[7]=t("的副教授 Greg R. Vetter 這樣説道。",-1))]),e[28]||(e[28]=p('<p>他回答 LinuxInsider 説，第二版 GPL 許可證被某些人認為提供了隱含的專利許可，但是律師們更喜歡明確的許可。</p><p>OIN 所提供的許可填補了這個空白。它還明確的覆蓋了 Linux 內核。據 Vetter 説，明確的專利許可並不是 GPLv2 中的必要部分，但是這個部分被加入到了 GPLv3 中。（LCTT 譯註：Linux 內核採用的是 GPLv2 的許可）</p><p>拿一個在 GPLv3 中寫了10000行代碼的代碼編寫者來説。隨着時間推移，其他的代碼編寫者會貢獻更多行的代碼，也加入到了知識產權中。GPLv3 中的軟件專利許可條款將基於所有參與的貢獻者的專利，保護全部代碼的使用，Vetter 如此説道。</p><h3 id="並不完全一樣" tabindex="-1">並不完全一樣 <a class="header-anchor" href="#並不完全一樣" aria-label="Permalink to “並不完全一樣”">​</a></h3><p>專利權和許可證在法律結構上層層疊疊互相覆蓋。弄清兩者對開源軟件的作用就像是穿越雷區。</p><p>Vetter 説“通常，許可證是授予建立在專利和版權法律上的額外權利的法律結構。許可證被認為是給予了人們做一些的可能會侵犯到其他人的知識產權權利的事的許可。”</p><p>Vetter 指出，很多自由開源許可證（例如 Mozilla 公共許可、GNU GPLv3 以及 Apache 軟件許可）融合了某些互惠專利權的形式。Vetter 指出，像 BSD 和 MIT 這樣舊的許可證不會提到專利。</p><p>一個軟件的許可證讓其他人可以在某種程度上使用這個編程人員創造的代碼。版權對所屬權的建立是自動的，只要某個人寫或者畫了某個原創的東西。然而，版權只覆蓋了個別的表達方式和衍生的作品。他並沒有涵蓋代碼的功能性或可用的想法。</p><p>專利涵蓋了功能性。專利權還可以被許可。版權可能無法保護某人如何獨立地開發對另一個人的代碼的實現，但是專利填補了這個小瑕疵，Vetter 解釋道。</p><h3 id="尋找安全通道" tabindex="-1">尋找安全通道 <a class="header-anchor" href="#尋找安全通道" aria-label="Permalink to “尋找安全通道”">​</a></h3>',10)),n("p",null,[e[10]||(e[10]=t("許可證和專利混合的法律性質可能會對開源開發者產生威脅。據 ",-1)),r(i,{href:"http://www.chaoticmoon.com/"},{default:l(()=>[...e[8]||(e[8]=[t("Chaotic Moon Studios",-1)])]),_:1}),e[11]||(e[11]=t(" 的創辦者之一、 ",-1)),r(i,{href:"http://www.ieee.org/"},{default:l(()=>[...e[9]||(e[9]=[t("IEEE",-1)])]),_:1}),e[12]||(e[12]=t(" 計算機協會成員 William Hurley 説，對於某些人來説，即使是 GPL 也會成為威脅。",-1))]),e[29]||(e[29]=p('<p>“在很久以前，開源是個完全不同的世界。被彼此間的尊重和把代碼視為藝術而非資產的觀點所驅動，那時的程序和代碼比現在更加的開放。我相信很多為最好的願景所做的努力幾乎最後總是揹負着意外的結果，”Hurley 這樣告訴 LinuxInsider。</p><p>他暗示説，成員人數超越了1000人（的組織）可能會在知識產權保護重要性方面意見不一。這可能會繼續攪混開源生態系統這灘渾水。</p><p>“最終，這些顯現出了圍繞着知識產權的常見的一些錯誤概念。擁有幾千個開發者並不會減少風險——而是增加。給出了專利許可的開發者越多，它們看起來就越值錢，”Hurley 説。“它們看起來越值錢，有着類似專利的或者其他知識產權的人就越可能試圖利用並從中榨取他們自己的經濟利益。”</p><h3 id="共享與競爭共存" tabindex="-1">共享與競爭共存 <a class="header-anchor" href="#共享與競爭共存" aria-label="Permalink to “共享與競爭共存”">​</a></h3><p>競合策略是開源的一部分。OIN 模型讓各個公司能夠決定他們將在哪競爭以及在哪合作，Bergelt 解釋道。</p><p>“開源演化中的許多改變已經把我們移到了另一個方向上。我們必須為合作創造渠道。否則我們將會有幾百個團體把數十億美元花費到同樣的技術上，”他説。</p><p>手機產業的革新就是個很好的例子。各個公司放出了不同的標準。沒有共享，沒有合作，Bergelt 解釋道。</p><p>他説：“這讓我們在美國接觸技術的能力落後了七到十年。我們接觸設備的經驗遠遠落後於世界其他地方的人。在我們用不上 CDMA (Code Division Multiple Access 碼分多址訪問通信技術)時對 GSM (Global System for Mobile Communications 全球移動通信系統) 還沾沾自喜。”</p><h3 id="改變格局" tabindex="-1">改變格局 <a class="header-anchor" href="#改變格局" aria-label="Permalink to “改變格局”">​</a></h3><p>OIN 在去年經歷了激增400個新許可的增長。這意味着着開源有了新趨勢。</p><p>Bergelt 説：“市場到達了一個臨界點，組織內的人們終於意識到直白地合作和競爭的需要。結果是兩件事同時進行。這可能會變得複雜、費力。”</p><p>然而，這個由人們開始考慮合作和競爭的文化革新所驅動的轉換過程是可以接受的。他解釋説，這也是一個人們怎樣擁抱開源的轉變——尤其是在 Linux 這個開源社區的領導者項目。</p><p>還有一個跡象是，最具意義的新項目都沒有在 GPLv3 許可下開發。</p><h3 id="二個總比一個好" tabindex="-1">二個總比一個好 <a class="header-anchor" href="#二個總比一個好" aria-label="Permalink to “二個總比一個好”">​</a></h3><p>“GPL 極為重要，但是事實是有一堆的許可模型正被使用着。在 Eclipse、Apache 和 Berkeley 許可中，專利問題的相對可解決性通常遠遠低於在 GPLv3 中的。”Bergelt 説。</p><p>GPLv3 對於解決專利問題是個自然的補充——但是 GPL 自身不足以獨自解決圍繞專利使用的潛在衝突。所以 OIN 的設計是以能夠補充版權許可為目的的，他補充道。</p><p>然而，層層疊疊的專利和許可也許並沒有帶來多少好處。到最後，專利在幾乎所有的案例中都被用於攻擊目的——而不是防禦目的，Bergelt 暗示説。</p><p>“如果你不準備對其他人採取法律行動，那麼對於你的知識產權來説專利可能並不是最佳的法律保護方式”，他説。“我們現在生活在一個對軟件——開放的和專有的——誤會重重的世界裏。這些軟件還被錯誤而過時的專利系統所捆綁。我們每天在工業化和被扼殺的創新中掙扎”，他説。</p><h3 id="法院是最後的手段" tabindex="-1">法院是最後的手段### <a class="header-anchor" href="#法院是最後的手段" aria-label="Permalink to “法院是最後的手段###”">​</a></h3><p>想到 OIN 的出現抑制了訴訟的泛濫就感到十分欣慰，Bergelt 説，或者至少可以説 OIN 的出現扼制了特定的某些威脅。</p><p>“可以説我們讓人們放下他們的武器。同時我們正在創建一種新的文化規範。一旦你入股這個模型中的非侵略專利，所產生的相關影響就是對合作的鼓勵”，他説。</p><p>如果你願意承諾合作，你的第一反應就會趨向於不急着起訴。相反的，你會想如何讓我們允許你使用我們所擁有的東西並讓它為你賺錢，而同時我們也能使用你所擁有的東西，Bergelt 解釋道。</p><p>“OIN 是個多面的解決方式。它鼓勵簽署者創造雙贏協議”，他説，“這讓起訴成為最逼不得已的行為。那才是它的位置。”</p><h3 id="底線" tabindex="-1">底線### <a class="header-anchor" href="#底線" aria-label="Permalink to “底線###”">​</a></h3><p>Bergelt 堅信，OIN 的運作是為了阻止 Linux 受到專利傷害。在這個需要 Linux 的世界裏沒有訴訟的地方。</p><p>唯一臨近的是與微軟的移動之爭，這關係到行業的發展前景（原文： The only thing that comes close are the mobile wars with Microsoft, which focus on elements high in the stack. 不太理解，請指正。）。那些來自法律的挑戰可能是為了提高包括使用 Linux 產品的所屬權的成本，Bergelt 説。</p><p>儘管如此“這些並不是有關 Linux 訴訟”，他説。“他們的重點並不在於 Linux 的核心。他們關注的是 Linux 系統裏都有些什麼。”</p><hr>',28)),n("p",null,[e[14]||(e[14]=t("via: ",-1)),r(i,{href:"http://www.linuxinsider.com/story/Defending-the-Free-Linux-World-81512.html"},{default:l(()=>[...e[13]||(e[13]=[t("http://www.linuxinsider.com/story/Defending-the-Free-Linux-World-81512.html",-1)])]),_:1})]),n("p",null,[e[17]||(e[17]=t("作者：Jack M. Germain 譯者：",-1)),r(i,{href:"https://github.com/H-mudcup"},{default:l(()=>[...e[15]||(e[15]=[t("H-mudcup",-1)])]),_:1}),e[18]||(e[18]=t(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:l(()=>[...e[16]||(e[16]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[21]||(e[21]=t("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[19]||(e[19]=[t("LCTT",-1)])]),_:1}),e[22]||(e[22]=t(" 原創翻譯，",-1)),r(i,{href:"http://linux.cn/"},{default:l(()=>[...e[20]||(e[20]=[t("Linux中國",-1)])]),_:1}),e[23]||(e[23]=t(" 榮譽推出",-1))])])}const P=a(d,[["render",x]]);export{I as __pageData,P as default};
